"""只读复核首批十题：独立算法，不执行题库参考实现。"""
import ast,hashlib,html,itertools,json,random,re,time
from pathlib import Path
from collections import Counter,deque
from functools import lru_cache
import heapq,math
def convolution(text):
 v=list(map(int,text.split()));m,n,p,q=v[:4];matrix=v[4:4+m*n];kernel=v[4+m*n:];assert len(kernel)==p*q
 bound=p*q*max(map(abs,matrix),default=0)*max(map(abs,kernel),default=0);width=max(1,(bound.bit_length()+7)//8)
 def packed(values,negative):return int.from_bytes(b''.join((max(0,-value) if negative else max(0,value)).to_bytes(width,'little') for value in values),'little')
 reverse=[0]*((p-1)*n+q)
 for i in range(p):
  for j in range(q):reverse[(p-1-i)*n+q-1-j]=kernel[i*q+j]
 a,b=packed(matrix,False),packed(matrix,True);c,d=packed(reverse,False),packed(reverse,True)
 blobs=[value.to_bytes((m+p)*n*width,'little') for value in (a*c,b*d,a*d,b*c)]
 def coefficient(index):
  start=index*width;parts=[int.from_bytes(blob[start:start+width],'little') for blob in blobs];return parts[0]+parts[1]-parts[2]-parts[3]
 return '\n'.join(' '.join(str(coefficient((r+p-1)*n+s+q-1)) for s in range(n-q+1)) for r in range(m-p+1))

def laplacian(text):
 from collections import Counter
 v=list(map(int,text.split()));n,m=v[:2];assert len(v)==2+2*m
 counts=Counter()
 for u,w in zip(v[2::2],v[3::2]):
  if u!=w:counts[u,w]+=1;counts[w,u]+=1
 return '\n'.join(' '.join(str(sum(counts[u,w] for w in range(n)) if u==z else -counts[u,z]) for z in range(n)) for u in range(n))

def hamburgers(text):
 v=list(map(int,text.split()));m,n=v[:2];skills=v[2:2+m];jobs=v[2+m:];assert len(jobs)==n
 # 阈值二分图的Hall亏量：难度至少t的产品，只能由熟练度至少t的工人覆盖。
 # 每个阈值的供需缺口取最大，同时计入工人总数不足的缺口。
 worker=sorted(skills);products=sorted(jobs)
 import bisect
 deficit=max(0,n-m)
 for i,t in enumerate(products):
  deficit=max(deficit,n-i-(m-bisect.bisect_left(worker,t)))
 return str(n-deficit)

def entities(text):
 lines=text.splitlines();assert len(lines)==int(lines[0])+1
 # 每个连续标注词段仅匹配一次；每句独立匹配，避免跨句合并。
 pattern=r'(?<!\S)###[^#\s]+###(?:\s+###[^#\s]+###)*(?!\S)'
 return str(sum(len(re.findall(pattern,line)) for line in lines[1:]))

def snake(text):
 (r,c),(x,y),(dx,dy)=[list(map(int,line.split())) for line in text.splitlines()]
 seen={(x,y)};centers=set()
 while True:
  a,b=x+dx,y+dy
  # 在边界外的法向分量被去掉，形成沿边界滑行的一步；随后反射法向方向。
  if not 0<=a<=r:a=x;dx=-dx
  if not 0<=b<=c:b=y;dy=-dy
  center=(x+a,y+b) if a!=x and b!=y else None
  if (a,b) in seen or (center is not None and center in centers):break
  if center is not None:centers.add(center)
  seen.add((a,b));x,y=a,b
  if x in (0,r) and y in (0,c):break
 return str(len(seen))

def matrix_product(text):
 rows=[list(map(int,l.split())) for l in text.splitlines()];n,m1,m2=rows[0];assert len(rows)==1+m1+m2
 # 展成稠密矩阵，再按行与列做整数内积，独立于参考解的三元组两两联结。
 a=[[0]*n for _ in range(n)];b=[[0]*n for _ in range(n)]
 for i,j,v in rows[1:1+m1]:a[i][j]=v
 for i,j,v in rows[1+m1:]:b[i][j]=v
 cols=list(zip(*b));out=[]
 for i,row in enumerate(a):
  for j,col in enumerate(cols):
   value=sum(x*y for x,y in zip(row,col))
   if value:out.append(f'{i} {j} {value}')
 return '\n'.join(out)

def frog(text):
 n=int(text)
 # 选k次跳2，其余跳1：总步数n-k，选其中k个位置。
 return str(sum(math.comb(n-k,k) for k in range(n//2+1)))

def seats(text):
 lines=[list(map(int,line.split())) for line in text.splitlines()];m,c=lines[0];assert len(lines)==m+1
 active=[];total=0
 for count,start,duration in sorted(lines[1:],key=lambda group:group[1]):
  if duration==0:continue
  while active and active[0][0]<=start:total-=heapq.heappop(active)[1]
  total+=count;heapq.heappush(active,(start+duration,count))
  if total>c:return 'N'
 return 'Y'

def strange(text):
 lines=text.splitlines();t=int(lines[0]);assert len(lines)==1+2*t;answers=[]
 for i in range(t):
  n=int(lines[1+2*i]);a=list(map(int,lines[2+2*i].split()));assert len(a)==n
  # 依已求得的DP长度分层，层中存放全部末项的按位或；从最长层向下查找可接的层。
  # 与参考解按30个比特维护最大DP不同；本算法最坏二次，仅用于只读答案审核。
  layers=[0]
  for x in a:
   k=len(layers)-1
   while k and layers[k]&x==0:k-=1
   k+=1
   if k==len(layers):layers.append(x)
   else:layers[k]|=x
  answers.append(str(len(layers)-1))
 return '\n'.join(answers)

def hop_path(start,target):
 # 深度迭代，先H后O；只使用乘3/除2的可达上下界剪枝，不假设坐标截断上限。
 powers=[3**k for k in range(26)]
 @lru_cache(None)
 def feasible(x,left):
  if left==0:return '' if x==target else None
  if x==0 or x*powers[left]<target or (x>>left)>target:return None
  for letter,y in (('H',3*x),('O',x//2)):
   suffix=feasible(y,left-1)
   if suffix is not None:return letter+suffix
  return None
 for depth in range(26):
  answer=feasible(start,depth)
  if answer is not None:return answer
 raise ValueError('无25步内解')

def hop(text):
 out=[]
 for line in text.splitlines():
  n,m=map(int,line.split())
  if n==m==0:break
  path=hop_path(n,m);out.extend([str(len(path)),path])
 return '\n'.join(out)+'\n'

SOLVERS={19942:convolution,19943:laplacian,19946:hamburgers,19949:entities,20137:snake,23555:matrix_product,23556:frog,25684:seats,26998:strange,27237:hop}
METHODS={19942:'正负系数分离的整数打包多项式乘法',19943:'邻接计数与行和度数重建',19946:'阈值二分图的Hall最大亏量',19949:'正则匹配各句连续标注词段',20137:'几何轨迹模拟，记录整数点及对角线中点',23555:'稠密矩阵行列整数内积',23556:'精确整数二项式求和',25684:'按到达时间扫描，用最小堆释放到期组',26998:'按DP长度分层、聚合末项按位或后查最长可接层',27237:'深度迭代与精确可达上下界剪枝，H优先保证字典序'}

def official_samples(n):
 page=Path(f'data/openjudge/pages/practice__{n}.html').read_text()
 bodies=[html.unescape(re.sub(r'<[^>]*>','',body)) for label,body in re.findall(r'<dt>(.*?)</dt>\s*<dd>(.*?)</dd>',page,re.S) if label in ('样例输入','样例输出')]
 joined='\n'.join(bodies)
 if n in (19943,26998):return [(bodies[0],bodies[1])]
 if n==20137:
  return [(m[0],m[1]) for m in re.findall(r'样例输入\d+：\s*([\d\s-]+?)\s*样例输出\d*：\s*(\d+)',joined)]
 if n==27237:
  return [(m[0],m[1]+'\n'+m[2]) for m in re.findall(r'sample\d+ in[：:]\s*([\d\s]+?)\s*sample\d+ out[：:]\s*(\d+)\s*([HO]+)',joined)]
 if n in (19942,19946,19949):pattern=r'Sample\d+ Input:\s*(.*?)Sample\d+ Output:\s*(.*?)(?=Sample\d+ Input:|\Z)'
 else:pattern=r'Sample Input\d+:\s*(.*?)Sample Output\d+:\s*(.*?)(?=Sample Input\d+:|\Z)'
 return [(a,b.split('解释：')[0].strip()) for a,b in re.findall(pattern,joined,re.S)]

def check(actual,expected):assert actual.split()==expected.split(),(actual[:100],expected[:100])

def brute_match(skills,jobs):
 match={}
 def augment(j,seen):
  for w,s in enumerate(skills):
   if s<jobs[j] or w in seen:continue
   seen.add(w)
   if w not in match or augment(match[w],seen):match[w]=j;return True
  return False
 return sum(augment(j,set()) for j in range(len(jobs)))

def segment_snake(text):
 # 小地图的另一种几何核对：对每一条旧线段用严格线段相交判据，允许共享起点。
 (r,c),pos,direction=[tuple(map(int,l.split())) for l in text.splitlines()];seen={pos};segments=[]
 def cross(a,b,c):return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
 while True:
  x,y=pos;dx,dy=direction
  if x+dx not in range(r+1):nxt=(x,y+dy);direction=(-dx,dy)
  elif y+dy not in range(c+1):nxt=(x+dx,y);direction=(dx,-dy)
  else:nxt=(x+dx,y+dy)
  if nxt in seen:break
  if any(cross(pos,nxt,a)*cross(pos,nxt,b)<0 and cross(a,b,pos)*cross(a,b,nxt)<0 for a,b in segments):break
  seen.add(nxt);segments.append((pos,nxt));pos=nxt
  if pos[0] in (0,r) and pos[1] in (0,c):break
 return str(len(seen))

def selfcheck():
 rng=random.Random(20261023);counts={n:0 for n in SOLVERS}
 for _ in range(200):
  m,n=rng.randint(1,7),rng.randint(1,7);p,q=rng.randint(1,m),rng.randint(1,n);a=[rng.randint(-20,20) for _ in range(m*n)];b=[rng.randint(-20,20) for _ in range(p*q)];text=f'{m} {n} {p} {q}\n'+' '.join(map(str,a+b));want=[sum(a[(r+i)*n+s+j]*b[i*q+j] for i in range(p) for j in range(q)) for r in range(m-p+1) for s in range(n-q+1)];assert list(map(int,convolution(text).split()))==want;counts[19942]+=1
  n=rng.randint(1,9);edges=[(u,v) for u in range(n) for v in range(u+1,n) if rng.randrange(2)];inc=[[int(u==v)-int(w==v) for u,w in edges] for v in range(n)];want=[sum(a*b for a,b in zip(inc[i],inc[j])) for i in range(n) for j in range(n)];text=f'{n} {len(edges)}\n'+'\n'.join(f'{u} {w}' for u,w in edges);assert list(map(int,laplacian(text).split()))==want;counts[19943]+=1
  a=[rng.randint(-3,7) for _ in range(rng.randint(1,8))];b=[rng.randint(-3,7) for _ in range(rng.randint(1,8))];text=f'{len(a)} {len(b)}\n'+' '.join(map(str,a))+'\n'+' '.join(map(str,b))+'\n';assert int(hamburgers(text))==brute_match(a,b);counts[19946]+=1
  lines=[];want=0
  for i in range(rng.randint(1,5)):
   flags=[bool(rng.randrange(2)) for _ in range(rng.randint(1,12))];want+=sum(tag and (j==0 or not flags[j-1]) for j,tag in enumerate(flags));lines.append(' '.join('###w###' if f else 'w' for f in flags))
  text=str(len(lines))+'\n'+'\n'.join(lines)+'\n';assert int(entities(text))==want;counts[19949]+=1
  n=rng.randint(1,5);a=[[rng.randint(-2,2) for j in range(n)] for i in range(n)];b=[[rng.randint(-2,2) for j in range(n)] for i in range(n)];aa=[(i,j,a[i][j]) for i in range(n) for j in range(n) if a[i][j]];bb=[(i,j,b[i][j]) for i in range(n) for j in range(n) if b[i][j]];triples=aa+bb;text=f'{n} {len(aa)} {len(bb)}\n'+''.join(' '.join(map(str,t))+'\n' for t in triples)
  # 通过逐项累加外积，校验稠密行列内积实现。
  acc=Counter()
  for i,k,x in aa:
   for l,j,y in bb:
    if k==l:acc[i,j]+=x*y
  want='\n'.join(f'{i} {j} {acc[i,j]}' for i,j in sorted(acc) if acc[i,j]);check(matrix_product(text),want);counts[23555]+=1
  m=rng.randint(1,10);capacity=rng.randint(1,15);groups=[(rng.randint(1,10),rng.randint(0,10),rng.randint(0,8)) for _ in range(m)];text=f'{m} {capacity}\n'+'\n'.join(' '.join(map(str,t)) for t in groups)+'\n';want='Y' if all(sum(cnt for cnt,s,d in groups if s<=t<s+d)<=capacity for t in range(19)) else 'N';assert seats(text)==want;counts[25684]+=1
  a=[rng.randint(1,63) for _ in range(rng.randint(1,12))];dp=[]
  for i,x in enumerate(a):dp.append(1+max([dp[j] for j in range(i) if a[j]&x]+[0]))
  text=f'1\n{len(a)}\n'+' '.join(map(str,a))+'\n';assert int(strange(text))==max(dp);counts[26998]+=1
 for n in range(1,17):
  def walks(left):return 1 if left==0 else sum(walks(left-step) for step in (1,2) if left>=step)
  assert int(frog(str(n)))==walks(n);counts[23556]+=1
 for r in range(1,8):
  for c in range(1,8):
   for x in range(r+1):
    for y in range(c+1):
     if (x in (0,r))==(y in (0,c)):continue
     for dx in (-1,1):
      for dy in (-1,1):
       if x==0 and dx!=1 or x==r and dx!=-1 or y==0 and dy!=1 or y==c and dy!=-1:continue
       text=f'{r} {c}\n{x} {y}\n{dx} {dy}\n';assert snake(text)==segment_snake(text),(text,snake(text),segment_snake(text));counts[20137]+=1
 for start in range(1,16):
  # 独立前向BFS仅用于小数域校验IDDFS的最短和字典序。
  q=deque([(start,'')]);seen={start};found={}
  while q and len(found)<15:
   x,path=q.popleft()
   if 1<=x<=15:found[x]=path
   for y,p in ((3*x,path+'H'),(x//2,path+'O')):
    if y not in seen:seen.add(y);q.append((y,p))
  for target,want in found.items():assert hop_path(start,target)==want;(counts.__setitem__(27237,counts[27237]+1))
 return counts

def run():
 counts=selfcheck();print('独立算法自检通过',counts,flush=True)
 triage=json.load(open('collab/gmyhf-pending-triage.json'));entries={e['global_number']:e for e in triage['entries']};result={'selfchecks':counts,'entries':[]}
 for n,solver in SOLVERS.items():
  samples=official_samples(n);assert samples,n
  for given,want in samples:check(solver(given.strip()+"\n"),want)
  e=entries[n];base=Path('data/openjudge/tests/admin_download')/str(n);rows=[]
  for record in e['read_only_comparison']['records']:
   inf=base/record['input'];outf=base/record['output']
   for k,f in [('input',inf),('output',outf)]:assert hashlib.sha256(f.read_bytes()).hexdigest()==record[k+'_sha256']
   started=time.monotonic();actual=solver(inf.read_text(encoding='utf-8-sig'));expected=outf.read_text(encoding='utf-8-sig');matches=actual.split()==expected.split();rows.append({**record,'matches':matches,'oracle_ms':round(1000*(time.monotonic()-started))})
   if not matches:print('答案不一致',n,record['input'],actual[:100],expected[:100],flush=True)
  result['entries'].append({'global_number':n,'method':METHODS[n],'official_samples':len(samples),'selfchecks':counts[n],'cases':len(rows),'all_answers_match':all(r['matches'] for r in rows),'files':rows})
  Path('/tmp/gmyhf-batch1-oracles.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(n,'官方样例',len(samples),'下载答案',sum(r['matches'] for r in rows),'/',len(rows),flush=True)
if __name__=='__main__':run()
